def agent_skill_bundle(
    self, project_id: str, intent: str, selected_skill_ids: list[str] | None = None
) -> tuple[dict[str, FileData], list[str]]:
    """Build a bounded virtual /skills tree for Deep Agents progressive disclosure."""
    candidates: list[InstalledSkill] = []
    allowed_ids = set(selected_skill_ids or [])
    if allowed_ids:
        enabled_ids = {item.skill_id for item in self.list_enabled(project_id)}
        unknown = allowed_ids - enabled_ids
        if unknown:
            raise ValueError(f"Skills are not enabled in this project: {sorted(unknown)}")
    for enabled in self.list_enabled(project_id):
        if allowed_ids and enabled.skill_id not in allowed_ids:
            continue
        skill = self.repository.session.get(InstalledSkill, enabled.skill_id)
        if not skill:
            continue
        front_matter = skill.manifest.get("front_matter", {})
        if not isinstance(front_matter, dict):
            continue
        applies_to = front_matter.get("applies_to", ["all"])
        if isinstance(applies_to, str):
            applies_to = [applies_to]
        if not isinstance(applies_to, list):
            continue
        scopes = {str(item) for item in applies_to}
        if {"all", intent} & scopes:
            candidates.append(skill)
    if intent == "reporting" and not any(
        skill.name == "complete-analysis-report" for skill in candidates
    ):
        builtins = [
            skill
            for skill in self.list_installed()
            if skill.name == "complete-analysis-report"
        ]
        if builtins:
            candidates.append(max(builtins, key=lambda skill: (skill.created_at, skill.id)))

    files: dict[str, FileData] = {}
    selected_ids: list[str] = []
    emitted_names: set[str] = set()
    copied_bytes = 0
    for skill in candidates:
        if skill.id in selected_ids or skill.name in emitted_names:
            continue
        root = Path(skill.path).resolve()
        safe_name = skill.name
        added = False
        for path in sorted(item for item in root.rglob("*") if item.is_file()):
            resolved = path.resolve()
            resolved.relative_to(root)
            if resolved.suffix.lower() not in AGENT_SKILL_TEXT_SUFFIXES:
                continue
            content = resolved.read_text(encoding="utf-8")
            size = len(content.encode("utf-8"))
            if copied_bytes + size > MAX_AGENT_SKILL_CONTEXT_BYTES:
                break
            virtual_path = f"/skills/{safe_name}/{resolved.relative_to(root).as_posix()}"
            files[virtual_path] = create_file_data(content)
            copied_bytes += size
            added = True
        if added:
            selected_ids.append(skill.id)
            emitted_names.add(skill.name)
        if copied_bytes >= MAX_AGENT_SKILL_CONTEXT_BYTES:
            break
    return files, selected_ids

def attach_file(
    self,
    project_id: str,
    source_type: SourceType,
    upload: Path,
    original_name: str | None = None,
) -> Source:
    if source_type not in {SourceType.CSV, SourceType.EXCEL, SourceType.SQLITE}:
        raise ValueError(f"File attachment does not support {source_type}")
    expected_suffixes = {
        SourceType.CSV: {".csv"},
        SourceType.EXCEL: {".xlsx", ".xls"},
        SourceType.SQLITE: {".sqlite", ".sqlite3", ".db"},
    }[source_type]
    suffix = Path(original_name or upload.name).suffix.lower()
    if suffix not in expected_suffixes:
        raise ValueError(
            f"File extension {suffix or '<none>'} does not match {source_type.value}"
        )
    existing_bytes = sum(
        source_bytes(source.baseline)
        for source in self.repository.list_sources(project_id)
        if source.type
        in {SourceType.CSV.value, SourceType.EXCEL.value, SourceType.SQLITE.value}
    )
    if existing_bytes + upload.stat().st_size > get_settings().max_project_source_bytes:
        raise ValueError("Project source files exceed the configured 2 GB default limit")
    copied = copy_source(project_id, upload, original_name)
    fingerprint = sha256(copied)
    source = self.repository.add_source(
        project_id,
        source_type.value,
        copied.name,
        fingerprint,
        {"path": str(copied)},
        {
            "format": source_type.value,
            "bytes": copied.stat().st_size,
            "profiled_at": None,
        },
        status="pending",
    )
    source.status = "profiling"
    self.repository.session.commit()
    try:
        baseline = {
            SourceType.CSV: profile_csv,
            SourceType.EXCEL: profile_excel,
            SourceType.SQLITE: profile_sqlite,
        }[source_type](copied)
        baseline["source_sha256"] = fingerprint
        baseline["bytes"] = copied.stat().st_size
        source.baseline = baseline
        source.status = "ready"
        self.repository.session.commit()
        return source
    except Exception as exc:
        source.status = "failed"
        source.baseline = {
            **source.baseline,
            "profile_error": type(exc).__name__,
            "failed_at": datetime.now(UTC).isoformat(),
        }
        self.repository.session.commit()
        raise

class QueryService:
    def __init__(self, repository: Repository):
        self.repository = repository
        self.settings = get_settings()

    def run(
        self,
        project_id: str,
        source_id: str,
        sql: str,
        name: str,
        analysis_dimension: str | None = None,
        business_question: str | None = None,
        finding_label: str | None = None,
        finding_metric: str | None = None,
        finding_unit: str | None = None,
        metric_additive: bool | None = None,
    ) -> Artifact:
        source = self.repository.get_source(project_id, source_id)
        if source.status != "ready":
            raise ValueError("Source changed since profiling; reprofile it before querying")
        dialect = "mysql" if source.type == "mysql" else "sqlite"
        statement = validate_read_only_sql(sql, dialect=dialect)
        if source.type == "csv":
            validate_file_query_scope(statement)
        elif source.type == "excel":
            raw_sheets = source.baseline.get("sheets", [])
            registered_sheets = {
                str(sheet.get("name"))
                for sheet in (raw_sheets if isinstance(raw_sheets, list) else [])
                if isinstance(sheet, dict) and sheet.get("name")
            }
            validate_file_query_scope(statement, registered_sheets)
        elif source.type == "mysql":
            raw_tables = source.baseline.get("tables", [])
            registered_tables = {
                str(item.get("name"))
                for item in (raw_tables if isinstance(raw_tables, list) else [])
                if isinstance(item, dict) and item.get("name")
            }
            validate_mysql_query_scope(statement, registered_tables)
        bounded_sql = apply_limit(statement, self.settings.query_row_limit, dialect=dialect)
        outer_aggregate = statement.args.get("group") is not None or any(
            projection.find(exp.AggFunc) is not None for projection in statement.expressions
        )
        query_shape = "aggregate" if outer_aggregate else "detail"

        if source.type == "csv":
            frame = self._query_csv(Path(str(source.config["path"])), bounded_sql)
        elif source.type == "excel":
            frame = self._query_excel(Path(str(source.config["path"])), bounded_sql)
        elif source.type == "sqlite":
            frame = self._query_sqlite(Path(str(source.config["path"])), bounded_sql)
        elif source.type == "mysql":
            frame = self._query_mysql(source, bounded_sql)
        else:
            raise ValueError(f"Unsupported source type: {source.type}")

        run_id = str(uuid4())
        root = project_root(project_id)
        query_path = root / "queries" / f"{run_id}.sql"
        query_path.write_text(bounded_sql + "\n", encoding="utf-8")
        output = root / "datasets" / "extracts" / f"{run_id}.parquet"
        frame.to_parquet(output, index=False)
        artifact = self.repository.add_artifact(
            project_id,
            "extract",
            name,
            output,

class AnalysisService:
    def __init__(self, repository: Repository):
        self.repository = repository

    def profile(self, project_id: str, artifact_id: str, name: str) -> Artifact:
        source, frame = load_tabular_artifact(self.repository, project_id, artifact_id)
        numeric = frame.select_dtypes(include=[np.number])
        fields: list[dict[str, Any]] = []
        for column in frame.columns:
            series = frame[column]
            field: dict[str, Any] = {
                "name": str(column),
                "dtype": str(series.dtype),
                "nulls": int(series.isna().sum()),
                "null_rate": float(series.isna().mean()),
                "unique": int(series.nunique(dropna=True)),
            }
            if column in numeric:
                values = pd.to_numeric(series, errors="coerce").dropna()
                if not values.empty:
                    q1, q3 = values.quantile([0.25, 0.75])
                    iqr = q3 - q1
                    field.update(
                        {
                            "min": float(values.min()),
                            "median": float(values.median()),
                            "mean": float(values.mean()),
                            "max": float(values.max()),
                            "outliers_iqr": int(
                                ((values < q1 - 1.5 * iqr) | (values > q3 + 1.5 * iqr)).sum()
                            ),
                        }
                    )
            fields.append(field)
        correlations = (
            numeric.corr(numeric_only=True).round(5).where(pd.notna(numeric.corr()), None).to_dict()
            if 1 < len(numeric.columns) <= 80
            else {}
        )
        payload = {
            "schema_version": 1,
            "rows": len(frame),
            "columns": len(frame.columns),
            "duplicate_rows": int(frame.duplicated().sum()),
            "missing_cells": int(frame.isna().sum().sum()),
            "fields": fields,
            "correlations": correlations,
        }
        path = project_root(project_id) / "datasets" / "derived" / f"{uuid4()}-profile.json"
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        return self.repository.add_artifact(project_id, "profile", name, path, payload, [source.id])

class ModelJobManager:
    def __init__(self) -> None:
        self.context = multiprocessing.get_context("spawn")
        self.jobs: dict[str, ModelJob] = {}
        self.lock = threading.Lock()

    def start(
        self, repository: Repository, project_id: str, payload: ModelRunRequest
    ) -> dict[str, object]:
        repository.get_project(project_id)
        repository.get_artifact(project_id, payload.artifact_id)
        with self.lock:
            for existing in self.jobs.values():
                self._refresh(existing)
            active = sum(job.status == "running" for job in self.jobs.values())
            if active >= 2:
                raise ValueError("At most two local model jobs may run concurrently")
            job_id = str(uuid4())
            result_queue = self.context.Queue()
            process = self.context.Process(
                target=_run_model_job,
                args=(project_id, payload.model_dump(), result_queue),
                name=f"northlight-model-{job_id[:8]}",
            )
            job = ModelJob(job_id, project_id, process, result_queue)
            self.jobs[job_id] = job
            process.start()
            return job.view()

    def status(self, project_id: str, job_id: str) -> dict[str, object]:
        job = self._get(project_id, job_id)
        self._refresh(job)
        return job.view()

    def cancel(self, project_id: str, job_id: str) -> dict[str, object]:
        job = self._get(project_id, job_id)
        self._refresh(job)
        if job.status == "running":
            job.process.terminate()
            job.process.join(timeout=5)
            if job.process.is_alive():
                job.process.kill()
                job.process.join(timeout=2)
            job.status = "cancelled"
            job.message = "训练已由用户取消"
        return job.view()

class MLService:
    def __init__(self, repository: Repository):
        self.repository = repository

    def run(
        self,
        project_id: str,
        artifact_id: str,
        task: str,
        target: str | None,
        features: list[str] | None,
        algorithm: str,
        name: str,
        random_state: int,
        tune: bool = False,
    ) -> dict[str, Artifact]:
        frame = load_artifact_frame(self.repository, project_id, artifact_id)
        selected_features = features or [column for column in frame.columns if column != target]
        missing = [
            column
            for column in selected_features + ([target] if target else [])
            if column not in frame
        ]
        if missing:
            raise ValueError(f"Columns not found: {', '.join(missing)}")
        if task == "clustering":
            return self._cluster(
                project_id, artifact_id, frame[selected_features], algorithm, name, random_state
            )
        if not target:
            raise ValueError("A target column is required for classification and regression")
        clean = frame[selected_features + [target]].dropna(subset=[target]).copy()
        clean, selected_features, date_features = self._expand_date_features(
            clean, selected_features
        )
        x = clean[selected_features]
        y = clean[target]
        stratify = y if task == "classification" and y.value_counts().min() >= 2 else None
        x_train, x_test, y_train, y_test = train_test_split(
            x, y, test_size=0.2, random_state=random_state, stratify=stratify
        )
        estimator = (
            classification_estimator(algorithm, random_state)
            if task == "classification"
            else regression_estimator(algorithm, random_state)
        )
        pipeline = Pipeline([("preprocess", build_preprocessor(x)), ("model", estimator)])
        scoring = "f1_weighted" if task == "classification" else "neg_mean_absolute_error"
        cv_scores: list[float] = []
        if len(clean) >= 30:
            try:
                cv_scores = [
                    float(value)
                    for value in cross_val_score(pipeline, x, y, cv=3, scoring=scoring, n_jobs=1)
                ]
            except ValueError:
                cv_scores = []
        best_params: dict[str, object] = {}
        grid = tuning_grid(task, algorithm)
        if tune and grid:
            search = GridSearchCV(pipeline, grid, cv=3, scoring=scoring, n_jobs=1)
            search.fit(x_train, y_train)
            pipeline = search.best_estimator_
            best_params = {
                key.replace("model__", ""): value for key, value in search.best_params_.items()
            }
        else:
            pipeline.fit(x_train, y_train)
        predictions = pipeline.predict(x_test)
        metrics = (
            self._classification_metrics(pipeline, x_test, y_test, predictions)
            if task == "classification"
            else self._regression_metrics(y_test, predictions)
        )
        metrics["cv_scores"] = cv_scores
        if cv_scores:
            metrics["cv_mean"] = float(np.mean(cv_scores))
            metrics["cv_std"] = float(np.std(cv_scores))
        metrics["feature_importance"] = self._feature_importance(pipeline)
        predictions_frame = x_test.copy()
        predictions_frame["actual"] = y_test
        predictions_frame["prediction"] = predictions
        return self._persist(
            project_id,
            artifact_id,
            pipeline,
            predictions_frame,
            {
                "task": task,
                "target": target,
                "features": selected_features,
                "date_features": date_features,
                "feature_schema": {column: str(x[column].dtype) for column in x.columns},
                "algorithm": algorithm,
                "random_state": random_state,
                "tuning": {"enabled": tune, "best_params": best_params},
                "train_rows": len(x_train),
                "test_rows": len(x_test),
                "metrics": metrics,
            },
            name,
        )

